import fs from 'node:fs/promises';
import {syncBuiltinESMExports} from 'node:module';
import {resolve} from 'node:path';
import {tmpdir} from 'node:os';
const repo=process.cwd();
const {initializeActiveFixture}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-fixture.mjs'));
const {activeWorker}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-worker.mjs'));
const parent=await fs.mkdtemp(resolve(tmpdir(),'lervo-io-probe-'));
const results=[];
function category(path){const p=String(path);return p.includes('/cas/')?'cas':p.endsWith('project.yaml')?'manifest':p.endsWith('event-contract.json')||p.includes('event-contract-activation')?'writer':p.includes('.sqlite')?'sqlite':'other'}
try{
 for(const workload of ['cold','warm','concurrent']){
  const root=resolve(parent,workload);await initializeActiveFixture(root);const phases={};const restorers=[];
  function timed(obj,key,label,after){const orig=obj[key];obj[key]=async function(...args){const start=performance.now();const result=phases[label(...args)]??={calls:0,ms:0};result.calls++;try{const value=await orig.apply(this,args);after?.(value,args);return value}finally{result.ms+=performance.now()-start}};restorers.push(()=>obj[key]=orig)}
  for(const name of ['lstat','mkdir','readFile','link','unlink','open'])timed(fs,name,(p)=>category(p)+'.'+name,name==='open'?(handle,args)=>{for(const key of ['write','sync','close','readFile','stat'])timed(handle,key,()=>category(args[0])+'.handle.'+key)}:undefined);
  syncBuiltinESMExports();let r;
  try{r=await activeWorker(root,'candidate',workload,4096,{warmups:2,samples:10,concurrency:4})}finally{for(const restore of restorers.reverse())restore();syncBuiltinESMExports()}
  results.push({workload,phases,samples:r.samples.map(s=>s.slice(0,2)),semanticValid:r.semanticValid});
 }
 await fs.writeFile('/tmp/lervo-recording-io-probe.json',JSON.stringify({diagnosticOnly:true,results},null,2));
}finally{await fs.rm(parent,{recursive:true,force:true})}

import fs from 'node:fs/promises';
import sync from 'node:fs';
import {syncBuiltinESMExports} from 'node:module';
import {resolve} from 'node:path';
import {tmpdir} from 'node:os';
const repo=process.cwd();
const {initializeActiveFixture}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-fixture.mjs'));
const {activeWorker}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-worker.mjs'));
const parent=await fs.mkdtemp(resolve(tmpdir(),'lervo-binding-stat-'));const results=[];
const original=fs.lstat;
try{
 for(let cycle=0;cycle<5;cycle++)for(const mode of cycle%2?['sync-binding','current']:['current','sync-binding'])for(const workload of ['cold','warm','concurrent']){
  const root=resolve(parent,`${cycle}-${mode}-${workload}`);await initializeActiveFixture(root);
  const bindingPaths=new Set([root,...['.lervo','.lervo/data','.lervo/state','.lervo/data/cas','.lervo/data/cas/sha256','.lervo/data/cas/.tmp','.lervo/data/events.sqlite'].map(p=>resolve(root,p))]);
  let calls=0,ms=0;
  fs.lstat=async(p,options)=>{const eligible=options?.bigint===true&&bindingPaths.has(String(p));const start=performance.now();try{return eligible&&mode==='sync-binding'?sync.lstatSync(p,options):await original(p,options)}finally{if(eligible){calls++;ms+=performance.now()-start}}};
  syncBuiltinESMExports();
  const r=await activeWorker(root,'candidate',workload,4096,{warmups:2,samples:10,concurrency:4});
  fs.lstat=original;syncBuiltinESMExports();results.push({cycle,mode,workload,calls,ms,semanticValid:r.semanticValid,integrity:r.integrity,eventCount:r.eventCount,expectedEventCount:r.expectedEventCount,samples:r.samples.map(s=>s.slice(0,2))});
 }
 await fs.writeFile('/tmp/lervo-binding-stat-probe.json',JSON.stringify({diagnosticOnly:true,results},null,2));
}finally{fs.lstat=original;syncBuiltinESMExports();await fs.rm(parent,{recursive:true,force:true})}

import { registerHooks } from 'node:module';
import { spawnSync } from 'node:child_process';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { tmpdir } from 'node:os';
const repo=process.cwd();
const worker=process.argv[2]==='worker';
if(worker){
 const [mode,root,workload]=process.argv.slice(3);
 let replacements=0;
 if(mode==='sync-binding')registerHooks({load(url,context,next){const result=next(url,context);if(!url.endsWith('/packages/project-storage/dist/storage-pool-binding.js'))return result;let source=String(result.source);const before=source;source=source.replace('import { lstat } from "node:fs/promises";','import { lstatSync } from "node:fs";').replace('await lstat(path, { bigint: true })','lstatSync(path, { bigint: true })');if(source===before||source.includes('await lstat('))throw Error('Prototype transform failed');replacements++;return {...result,source}}});
 const {activeWorker}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-worker.mjs'));
 const r=await activeWorker(root,'candidate',workload,4096,{warmups:2,samples:10,concurrency:4});
 process.stdout.write(JSON.stringify({mode,workload,replacements,semanticValid:r.semanticValid,integrity:r.integrity,eventCount:r.eventCount,expectedEventCount:r.expectedEventCount,samples:r.samples.map(s=>s.slice(0,2))}));
}else{
 const {initializeActiveFixture}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-fixture.mjs'));
 const parent=await mkdtemp(resolve(tmpdir(),'lervo-binding-isolated-'));const results=[];
 try{
  for(let cycle=0;cycle<5;cycle++)for(const workload of ['cold','warm','concurrent'])for(const mode of cycle%2?['sync-binding','current']:['current','sync-binding']){
   const root=resolve(parent,`${cycle}-${mode}-${workload}`);await initializeActiveFixture(root);
   const child=spawnSync(process.execPath,[process.argv[1],'worker',mode,root,workload],{encoding:'utf8',timeout:30000,maxBuffer:1048576});
   if(child.status!==0)throw Error(child.stderr||String(child.error));results.push({cycle,...JSON.parse(child.stdout)});
  }
  await writeFile('/tmp/lervo-binding-isolated-probe.json',JSON.stringify({diagnosticOnly:true,results},null,2));
 }finally{await rm(parent,{recursive:true,force:true})}
}

